<?php
namespace App\Http\Controllers;
use App\Services\DocumentIntegrationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DocumentIntegrationController extends Controller{
public function __construct(private DocumentIntegrationService $docs){}
private function allowed(Request $r,$module){$u=$r->user();$ok=$u->isSuperAdmin()||$u->hasRole('admin');if($module==='practice')$ok=$ok||$u->hasRole('practice_head')||$u->canDo('practice.manage');if($module==='dormitory')$ok=$ok||$u->hasRole('dormitory_manager')||$u->canDo('dormitory.manage');if($module==='upbringing')$ok=$ok||$u->hasRole('upbringing_head');if($module==='canteen')$ok=$ok||$u->hasRole('canteen_manager')||$u->canDo('canteen.manage');if($module==='students')$ok=$ok||$u->hasRole('academic_head')||$u->canDo('students.manage');abort_unless($ok,403);}
public function create(Request $r,$module,$type,$id){$this->allowed($r,$module);$p=$r->attributes->get('academic_period');$d=$r->validate(['document_type'=>'required|string|max:100','title'=>'required|string|max:500','direction'=>'nullable|in:incoming,outgoing,internal','summary'=>'nullable|string|max:10000','body'=>'nullable|string|max:50000']);$snapshot=$this->snapshot($module,$type,$id,$p->id);$doc=$this->docs->create($r->user(),$p->id,$module,$type,$id,$d['document_type'],$d['title'],$snapshot,['direction'=>$d['direction']??'internal','summary'=>$d['summary']??null,'body'=>$d['body']??null]);return redirect()->route('edo.show',$doc)->with('success','Проект документа создан и связан с исходной записью.');}
private function snapshot($m,$t,$id,$pid){if($m==='practice'&&$t==='mass_document'){$x=DB::table('practice_mass_documents')->find($id);abort_if(!$x,404);return ['source'=>$x,'data'=>json_decode($x->snapshot_json,true)];}if($m==='dormitory'&&$t==='order'){$x=DB::table('dormitory_order_drafts')->find($id);abort_if(!$x,404);return ['source'=>$x,'data'=>json_decode($x->snapshot_json,true)];}if($m==='canteen'&&$t==='meal_assignment'){$x=DB::table('student_meal_assignments')->find($id);abort_if(!$x,404);return ['assignment'=>$x,'student'=>DB::table('students')->find($x->student_id),'category'=>DB::table('meal_categories')->find($x->meal_category_id)];}if($m==='upbringing')return ['entity_type'=>$t,'entity_id'=>$id,'period_id'=>$pid,'captured_at'=>now()->toIso8601String()];if($m==='students')return ['entity_type'=>$t,'entity_id'=>$id,'period_id'=>$pid,'student'=>DB::table('students')->find($id),'captured_at'=>now()->toIso8601String()];abort(404);}
}